Generate a standalone C reproducer that triggers this vulnerability:

File: libtiff/tif_getimage.c
Line: 2972
Function: makecmap
Bug type: divide-by-zero
CWE: CWE-369
Explanation: nsamples is computed as 8 / bitspersample without validating that bitspersample is non-zero. If a crafted image sets BitsPerSample to 0 (propagating to img->bitspersample), calling makecmap() for palette images will divide by zero and crash.

Source context:
```c
     2932: static int checkcmap(TIFFRGBAImage *img)
     2933: {
     2934:     uint16_t *r = img->redcmap;
     2935:     uint16_t *g = img->greencmap;
     2936:     uint16_t *b = img->bluecmap;
     2937:     long n = 1L << img->bitspersample;
     2938: 
     2939:     while (n-- > 0)
     2940:         if (*r++ >= 256 || *g++ >= 256 || *b++ >= 256)
     2941:             return (16);
     2942:     return (8);
     2943: }
     2944: 
     2945: static void cvtcmap(TIFFRGBAImage *img)
     2946: {
     2947:     uint16_t *r = img->redcmap;
     2948:     uint16_t *g = img->greencmap;
     2949:     uint16_t *b = img->bluecmap;
     2950:     long i;
     2951: 
     2952:     for (i = (1L << img->bitspersample) - 1; i >= 0; i--)
     2953:     {
     2954: #define CVT(x) ((uint16_t)((x) >> 8))
     2955:         r[i] = CVT(r[i]);
     2956:         g[i] = CVT(g[i]);
     2957:         b[i] = CVT(b[i]);
     2958: #undef CVT
     2959:     }
     2960: }
     2961: 
     2962: /*
     2963:  * Palette images with <= 8 bits/sample are handled
     2964:  * with a table to avoid lots of shifts and masks.  The table
     2965:  * is setup so that put*cmaptile (below) can retrieve 8/bitspersample
     2966:  * pixel values simply by indexing into the table with one
     2967:  * number.
     2968:  */
     2969: static int makecmap(TIFFRGBAImage *img)
     2970: {
     2971:     int bitspersample = img->bitspersample;
>>>  2972:     int nsamples = 8 / bitspersample;
     2973:     uint16_t *r = img->redcmap;
     2974:     uint16_t *g = img->greencmap;
     2975:     uint16_t *b = img->bluecmap;
     2976:     uint32_t *p;
     2977:     int i;
     2978: 
     2979:     img->PALmap = (uint32_t **)_TIFFmallocExt(
     2980:         img->tif,
     2981:         256 * sizeof(uint32_t *) + (256 * nsamples * sizeof(uint32_t)));
     2982:     if (img->PALmap == NULL)
     2983:     {
     2984:         TIFFErrorExtR(img->tif, TIFFFileName(img->tif),
     2985:                       "No space for Palette mapping table");
     2986:         return (0);
     2987:     }
     2988:     p = (uint32_t *)(img->PALmap + 256);
     2989:     for (i = 0; i < 256; i++)
     2990:     {
     2991:         TIFFRGBValue c;
     2992:         img->PALmap[i] = p;
     2993: #define CMAP(x)                                                                \
     2994:     c = (TIFFRGBValue)x;                                                       \
     2995:     *p++ = PACK(r[c] & 0xff, g[c] & 0xff, b[c] & 0xff);
     2996:         switch (bitspersample)
     2997:         {
     2998:             case 1:
     2999:                 CMAP(i >> 7);
     3000:                 CMAP((i >> 6) & 1);
     3001:                 CMAP((i >> 5) & 1);
     3002:                 CMAP((i >> 4) & 1);
     3003:                 CMAP((i >> 3) & 1);
     3004:                 CMAP((i >> 2) & 1);
     3005:                 CMAP((i >> 1) & 1);
     3006:                 CMAP(i & 1);
     3007:                 break;
     3008:             case 2:
     3009:                 CMAP(i >> 6);
     3010:                 CMAP((i >> 4) & 3);
     3011:                 CMAP((i >> 2) & 3);
     3012:                 CMAP(i & 3);
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
